using System.Diagnostics;
using System.Security.Cryptography;
using System.Text.Json;

namespace TTC.Siren.Tests;

/// <summary>
/// Review M4-2 (M-1): golden data is bound to the Python reference source. The header written by the generators
/// (tools/parity/golden_sources.py) lists the SHA-256 of every file the golden content depends on plus the Python
/// major.minor version. This class recomputes both from the working tree; a golden file whose binding does not match
/// is stale and is regenerated by <see cref="GoldenFiles"/>. The file sets mirror golden_sources.py; a different set
/// in the header is a mismatch too, so the two can never drift apart silently.
/// </summary>
internal static class GoldenSources
{
    private static readonly string[] RulesPatterns =
    {
        "core/*.py", "csv_compat.py", "data/幻卡数据库.csv", "tools/parity/golden_sources.py", "tools/parity/py_rules_trace.py",
    };

    private static readonly string[] SearchPatterns = RulesPatterns.Concat(new[]
    {
        "ai/ai.py", "tools/parity/py_search_trace.py",
    }).ToArray();

    private static readonly string[] EndgamePatterns = SearchPatterns.Concat(new[]
    {
        "ai_server.py", "ai/unknown_card_handler.py", "config/unknown_card_config.py", "tools/parity/py_endgame_trace.py",
    }).ToArray();

    private static readonly string[] E2ePatterns = EndgamePatterns.Concat(new[]
    {
        "ai/csharp_engine.py", "tools/phase7/gen_corpus.py", "tools/phase7/e2e_reference.py",
    }).ToArray();

    private static string[] Patterns(string kind) => kind switch
    {
        "rules" or "carddb" => RulesPatterns,
        "search" => SearchPatterns,
        "endgame" => EndgamePatterns,
        "e2e" => E2ePatterns,
        _ => throw new ArgumentException("unknown golden kind " + kind),
    };

    /// <summary>The repository-relative files (forward slashes) a golden file of this kind must be bound to.</summary>
    public static SortedSet<string> Required(string repoRoot, string kind)
    {
        var files = new SortedSet<string>(StringComparer.Ordinal);
        foreach (string pattern in Patterns(kind))
        {
            if (pattern.Contains('*'))
            {
                string dir = Path.Combine(repoRoot, Path.GetDirectoryName(pattern)!);
                string filePattern = Path.GetFileName(pattern);
                foreach (string f in Directory.GetFiles(dir, filePattern))
                    files.Add(Path.GetRelativePath(repoRoot, f).Replace('\\', '/'));
            }
            else
            {
                files.Add(pattern);
            }
        }
        return files;
    }

    public static string Sha256(string repoRoot, string relativePath) =>
        Convert.ToHexString(SHA256.HashData(File.ReadAllBytes(Path.Combine(repoRoot, relativePath)))).ToLowerInvariant();

    private static readonly Lazy<string> LazyPythonVersion = new(() =>
    {
        var psi = new ProcessStartInfo("python", new[] { "-c", "import sys; print('%d.%d' % sys.version_info[:2])" })
        {
            RedirectStandardOutput = true,
            UseShellExecute = false,
        };
        using var proc = Process.Start(psi) ?? throw new InvalidOperationException("Could not start python");
        string text = proc.StandardOutput.ReadToEnd().Trim();
        proc.WaitForExit();
        return text;
    });

    public static string PythonVersion => LazyPythonVersion.Value;

    /// <summary>
    /// Null if the header (the object that holds <c>source_sha256</c> and <c>python_version</c>) matches the working
    /// tree and the running Python; otherwise a description of the first mismatch.
    /// </summary>
    public static string? Check(JsonElement header, string repoRoot, string kind, string pythonVersion)
    {
        if (!header.TryGetProperty("python_version", out var pv) || pv.ValueKind != JsonValueKind.String)
            return "header has no python_version (golden predates source binding)";
        if (pv.GetString() != pythonVersion)
            return $"golden was generated by Python {pv.GetString()}, running Python is {pythonVersion}";
        if (!header.TryGetProperty("source_sha256", out var sources) || sources.ValueKind != JsonValueKind.Object)
            return "header has no source_sha256 (golden predates source binding)";

        var required = Required(repoRoot, kind);
        var listed = new SortedSet<string>(sources.EnumerateObject().Select(p => p.Name), StringComparer.Ordinal);
        if (!required.SetEquals(listed))
        {
            string missing = string.Join(", ", required.Except(listed));
            string extra = string.Join(", ", listed.Except(required));
            return $"bound file set differs (missing in header: [{missing}], unexpected in header: [{extra}])";
        }
        foreach (string rel in required)
        {
            string expected = sources.GetProperty(rel).GetString() ?? "";
            string actual = Sha256(repoRoot, rel);
            if (!string.Equals(expected, actual, StringComparison.OrdinalIgnoreCase))
                return $"{rel} changed since the golden file was generated (sha256 {expected} -> {actual})";
        }
        return null;
    }
}
